import React from 'react';
import './ColorPicker.css';

const ColorPicker = ({ colors, selectedColor, onColorChange }) => {
  const getColorStyle = (color) => {
    const colorMap = {
      yellow: '#E6CA97',
      rose: '#E1A4A9', 
      white: '#D9D9D9'
    };
    return colorMap[color] || '#E6CA97';
  };

  const getColorName = (color) => {
    const nameMap = {
      yellow: 'Yellow Gold',
      rose: 'Rose Gold',
      white: 'White Gold'
    };
    return nameMap[color] || color;
  };

  return (
    <div className="color-picker-container">
      <div className="color-picker">
        {colors.map((color) => (
          <button
            key={color}
            className={`color-option ${selectedColor === color ? 'selected' : ''}`}
            style={{ backgroundColor: getColorStyle(color) }}
            onClick={() => onColorChange(color)}
            aria-label={`Select ${getColorName(color)}`}
          >
            {selectedColor === color && (
              <div className="color-check">
                <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
                  <path 
                    d="M8 2L3.5 6.5L2 5" 
                    stroke={color === 'white' ? '#333' : 'white'} 
                    strokeWidth="1.5" 
                    strokeLinecap="round" 
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
            )}
          </button>
        ))}
      </div>
      <span className="selected-color-name">{getColorName(selectedColor)}</span>
    </div>
  );
};

export default ColorPicker;
